// Keep the latest reading PER NODE, not one slot per sensor kind.
//
// The old single 'soil' slot meant soil-bed-2 overwrote soil-bed-1 and the page
// showed whichever reported last — with no hint the others existed. Keyed on node,
// a new bed appears by reporting rather than by an edit here.
//
// 'gaps' is a short rolling history of arrival intervals. The page uses its median
// to decide when a node has gone quiet, because a deep-sleep node at 10 minutes and
// farm-node at 60 seconds cannot share one fixed threshold.
const p = msg.payload;
const now = Date.now();
const key = "water:" + (p.node || "unknown");
const nodes = flow.get("nodes") || {};
const prev = nodes[key];

const gaps = (prev && prev.gaps) ? prev.gaps.slice() : [];
if (prev && prev.at) {
    gaps.push(now - prev.at);
    if (gaps.length > 8) gaps.shift();
}

nodes[key] = Object.assign({}, p, {
    kind: "water",
    node: p.node || "unknown",
    at: now,
    gaps: gaps
});
flow.set("nodes", nodes);

// The old single-slot keys stay written so nothing that still reads them breaks.
flow.set("water", Object.assign({}, p, { at: now }));

// ok:false means the ESP is alive and the probe is not. Show it as a fault
// rather than dropping it — that's a different repair job from silence.
if (p.ok === false) {
    node.status({ fill: "red", shape: "ring", text: "probe fault: " + p.error });
    return null;
}

let text = p.depth_mm + " mm";
if (p.percent !== undefined) text += "  (" + p.percent + "%)";
node.status({ fill: "green", shape: "dot", text: text });

return { payload: p.depth_mm, topic: p.node };

// Keep the latest reading PER NODE, not one slot per sensor kind.
//
// The old single 'soil' slot meant soil-bed-2 overwrote soil-bed-1 and the page
// showed whichever reported last — with no hint the others existed. Keyed on node,
// a new bed appears by reporting rather than by an edit here.
//
// 'gaps' is a short rolling history of arrival intervals. The page uses its median
// to decide when a node has gone quiet, because a deep-sleep node at 10 minutes and
// farm-node at 60 seconds cannot share one fixed threshold.
const p = msg.payload;
const now = Date.now();
const key = "soil:" + (p.node || "unknown");
const nodes = flow.get("nodes") || {};
const prev = nodes[key];

const gaps = (prev && prev.gaps) ? prev.gaps.slice() : [];
if (prev && prev.at) {
    gaps.push(now - prev.at);
    if (gaps.length > 8) gaps.shift();
}

nodes[key] = Object.assign({}, p, {
    kind: "soil",
    node: p.node || "unknown",
    at: now,
    gaps: gaps
});
flow.set("nodes", nodes);

// The old single-slot keys stay written so nothing that still reads them breaks.
flow.set("soil", Object.assign({}, p, { at: now }));

if (p.ok === false) {
    node.status({ fill: "red", shape: "ring", text: "probe fault: " + p.error });
    return null;
}

node.status({
    fill: "green", shape: "dot",
    text: (p.node || "soil") + ": " + p.moisture_pct + " %  |  " + p.temp_c + " C"
});

return { payload: p.moisture_pct, topic: p.node };

// A live page from core nodes only — no node-red-dashboard install. Every extra
// install step is a place a build dies on someone else's phone.
//
// Deliberately mirrors the cloud dashboard (farm.sunriselabs.io): one card per
// reporting node, the same colour semantics, the same valve panel. Same system,
// two windows — and this one keeps working with no internet at all, which is the
// whole reason it exists.
const now = Date.now();
const nodes = flow.get("nodes") || {};

function esc(s) {
    return String(s === undefined || s === null ? "" : s).replace(/[&<>"']/g, function (c) {
        return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
}

function ago(ms) {
    const s = Math.max(0, Math.round((now - ms) / 1000));
    if (s < 60) return s + "s ago";
    if (s < 3600) return Math.floor(s / 60) + "m ago";
    if (s < 86400) return Math.floor(s / 3600) + "h ago";
    return Math.floor(s / 86400) + "d ago";
}

// How long this node may be quiet before we call it stale — learned from its own
// arrival history, so the 10-minute sleep node and the 60-second farm-node can
// share a page without one of them being permanently wrong.
function staleAfter(r) {
    if (!r.gaps || r.gaps.length < 3) return 20 * 60000;
    const g = r.gaps.slice().sort(function (a, b) { return a - b; });
    const median = g[Math.floor(g.length / 2)] || 60000;
    return Math.max(3 * median, 5 * 60000);
}

const list = Object.keys(nodes).map(function (k) { return nodes[k]; });
list.sort(function (a, b) {
    const rank = function (r) { return r.kind === "water" ? 0 : r.kind === "soil" ? 1 : 2; };
    return rank(a) - rank(b) || String(a.node).localeCompare(String(b.node));
});

const cards = list.map(function (r) {
    const title = r.kind === "water" ? "Water tank" : r.kind === "soil" ? "Soil" : esc(r.kind);
    const quiet = now - r.at;
    const cls = r.ok === false ? "bad" : quiet > staleAfter(r) ? "stale" : "good";

    let body;
    if (r.ok === false) {
        body = '<p class="err">FAULT &mdash; ' + esc(r.error || "no error given") + "</p>";
    } else if (r.kind === "water") {
        body = '<p class="big">' + esc(r.depth_mm) + "<span>mm</span></p>";
        if (r.percent !== undefined) body += '<p class="s">' + esc(r.percent) + "% full</p>";
        if (r.raw !== undefined) body += '<p class="s">raw ' + esc(r.raw) + "</p>";
    } else {
        body = '<p class="big">' + esc(r.moisture_pct) + "<span>%</span></p>";
        const bits = [];
        if (r.temp_c !== undefined) bits.push(esc(r.temp_c) + " &deg;C");
        if (r.ec !== undefined) bits.push("EC " + esc(r.ec));
        if (r.vbat !== undefined) bits.push(esc(r.vbat) + " V");
        if (r.valve !== undefined) bits.push("valve " + (r.valve ? "OPEN" : "shut"));
        body += '<p class="s">' + bits.join(" &middot; ") + "</p>";
    }

    const meta = [ago(r.at)];
    if (cls === "stale") meta.push("<b>quiet</b>");
    if (r.rssi !== undefined) meta.push(esc(r.rssi) + " dBm");
    if (r.sleep_min !== undefined) meta.push("sleeps " + esc(r.sleep_min) + "m");

    return '<div class="c ' + cls + '"><h2>' + title
         + ' <span class="nm">' + esc(r.node) + "</span></h2>"
         + body
         + '<p class="s">' + meta.join(" &middot; ") + "</p></div>";
}).join("");

// Valve — MANUAL. flow.valveCmd is the DESIRED state (set by these buttons, or by
// the cloud dashboard arriving on a push response). The node echoes its ACTUAL pin
// state back in /soil as `valve`; commanded and confirmed are not the same thing.
const vcmd = flow.get("valveCmd") ? 1 : 0;
let confirmedBy = null, confirmedVal = null;
list.forEach(function (r) {
    if (r.valve !== undefined && r.valve !== null) { confirmedBy = r.node; confirmedVal = r.valve ? 1 : 0; }
});
const agrees = confirmedVal !== null && confirmedVal === vcmd;

const valveCard =
    '<div class="c valve' + (vcmd ? " open" : "") + '"><h2>Master valve</h2>'
  + '<p class="big">' + (vcmd ? "OPEN" : "SHUT") + "</p>"
  + '<div class="btns">'
  + '<button class="b bo" onclick="setValve(1)"' + (vcmd ? " disabled" : "") + ">Open</button>"
  + '<button class="b bc" onclick="setValve(0)"' + (vcmd ? "" : " disabled") + ">Shut</button>"
  + "</div>"
  + '<p class="s ' + (agrees ? "" : "err") + '">'
  + (confirmedVal === null
      ? "no node has reported a valve position yet"
      : agrees
        ? "confirmed " + (confirmedVal ? "open" : "shut") + " by " + esc(confirmedBy)
        : "&#9888; " + esc(confirmedBy) + " still reports " + (confirmedVal ? "OPEN" : "SHUT") + " &mdash; not applied yet")
  + "</p></div>";

// Backhaul health. If the cloud push is broken this is where you find out, rather
// than by noticing farm.sunriselabs.io has quietly stopped moving.
const ps = flow.get("pushState") || {};
const queued = (flow.get("outbox") || []).length;
const pushLine = ps.at
    ? (ps.ok ? "cloud sync OK &middot; " + ago(ps.at) : "&#9888; cloud sync failing &middot; " + esc(ps.error) + " &middot; " + ago(ps.at))
    : "cloud sync: nothing sent yet";

msg.headers = { "content-type": "text/html; charset=utf-8" };
msg.payload =
'<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
+ '<meta name="viewport" content="width=device-width,initial-scale=1">'
+ '<meta http-equiv="refresh" content="5">'
+ "<title>Farmers IoT &mdash; base station</title><style>"
+ "body{margin:0;padding:16px;background:#12161c;color:#e8eef6;"
+ "font-family:system-ui,-apple-system,sans-serif}"
+ "h1{font-size:1.1rem;font-weight:600;color:#8fa3bb;margin:0 0 4px}"
+ "h1 small{font-weight:400;opacity:.8}"
+ ".sync{font-size:.8rem;color:#8fa3bb;margin:0 0 16px}"
+ ".g{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr))}"
+ ".c{background:#1b212b;border-radius:12px;padding:18px;border-left:5px solid #3a4553}"
+ ".c.good{border-left-color:#3fb950}.c.stale{border-left-color:#d29922}"
+ ".c.bad{border-left-color:#f85149}.c.valve{border-left-color:#3a4553}"
+ ".c.valve.open{border-left-color:#3fb950}"
+ "h2{font-size:.8rem;text-transform:uppercase;letter-spacing:.08em;"
+ "color:#8fa3bb;margin:0 0 10px;font-weight:600}"
+ ".nm{text-transform:none;letter-spacing:0;font-weight:400;opacity:.75}"
+ ".big{font-size:2.6rem;font-weight:700;margin:0;line-height:1.1}"
+ ".big span{font-size:1rem;font-weight:500;color:#8fa3bb;margin-left:6px}"
+ ".s{margin:6px 0 0;font-size:.85rem;color:#8fa3bb}"
+ ".err{color:#f85149}"
+ ".c.bad .big{color:#f85149;font-size:1.8rem}"
+ ".btns{display:flex;gap:8px;margin-top:12px}"
+ ".b{flex:1;padding:12px;border:0;border-radius:8px;font-size:1rem;font-weight:600;"
+ "cursor:pointer;background:#2a323d;color:#e8eef6}"
+ ".b:disabled{opacity:.4;cursor:default}"
+ ".b.bo:not(:disabled){color:#3fb950}.b.bc:not(:disabled){color:#f85149}"
+ "footer{margin-top:16px;font-size:.75rem;color:#8fa3bb}"
+ "</style></head><body>"
+ "<h1>Farmers IoT Toolkit <small>&middot; base station</small></h1>"
+ '<p class="sync">' + pushLine + (queued ? " &middot; " + queued + " queued" : "") + "</p>"
+ '<div class="g">' + (cards || '<div class="c"><h2>No nodes yet</h2><p class="s">waiting for a first reading</p></div>') + valveCard + "</div>"
+ "<footer>This page works with no internet. Same data at farm.sunriselabs.io when the phone has signal.</footer>"
+ '<script>function setValve(v){'
+ 'document.querySelectorAll(".b").forEach(function(b){b.disabled=true;});'
+ 'fetch("/valve/set?v="+v,{method:"POST"}).then(function(){location.reload();});'
+ "}</script>"
+ "</body></html>";

return msg;

// The node polls this to learn the desired valve state. Plain "1"/"0" so the
// firmware needs no JSON parser. flow.valveCmd is set by the page buttons.
msg.payload = flow.get('valveCmd') ? '1' : '0';
msg.headers = { 'content-type': 'text/plain' };
return msg;

// The page's Open/Close buttons POST here with ?v=1 (open) or ?v=0 (close).
// This only records the DESIRED state; the node applies it on its next poll and
// reports back what the pin actually did.
const v = (msg.req && msg.req.query && msg.req.query.v) || msg.payload;
const on = String(v).indexOf('1') >= 0;
flow.set('valveCmd', on ? 1 : 0);
node.status({ fill: on ? 'green' : 'grey', shape: 'dot',
              text: on ? 'commanded OPEN' : 'commanded CLOSED' });
msg.payload = on ? '1' : '0';
msg.headers = { 'content-type': 'text/plain' };
return msg;

// Buffer every reading — good AND faulted — for the cloud push.
//
// Wired straight off the 'http in' nodes ON PURPOSE. The 'store water'/'store soil'
// functions return null when ok:false, so tapping them would drop exactly the rows
// that tell you a probe died. A silent node and a broken probe are different repairs.

const p = msg.payload || {};
const url = (msg.req && msg.req.url) || "";
const kind = url.indexOf("soil") !== -1 ? "soil"
           : url.indexOf("water") !== -1 ? "water"
           : (p.moisture_pct !== undefined ? "soil" : "water");

// client_id makes redelivery idempotent. A batch whose response is lost in a 4G
// dropout gets re-sent; without this key the server would count it twice, and it
// would do so precisely during bad signal — when the data matters most.
const seq = (flow.get("pushSeq") || 0) + 1;
flow.set("pushSeq", seq);

const row = Object.assign({}, p, {
    kind: kind,
    client_id: kind + ":" + (p.node || "unknown") + ":" + Date.now() + ":" + seq
});

const outbox = flow.get("outbox") || [];
outbox.push(row);

// ~17 hours of backlog for two sensors at 60 s. Past that, drop the OLDEST —
// during a long outage the newest readings are the ones worth having.
const CAP = 2000;
if (outbox.length > CAP) outbox.splice(0, outbox.length - CAP);
flow.set("outbox", outbox);

node.status({ fill: outbox.length > 50 ? "yellow" : "grey", shape: "ring", text: "queued " + outbox.length });

// Drain right here, on the arriving reading, rather than waiting for the timer.
//
// Android freezes Termux's JS timers whenever the phone dozes — a 30 s setInterval
// simply stops running, and the backlog grows forever while everything LOOKS fine.
// An incoming POST from the ESP has already woken the process, so draining on that
// event needs no wake-lock and no scheduler. The inject stays as a backstop.
return msg;

// ── EDIT HERE: where the readings go ────────────────────────────────────────
const INGEST_URL = "https://YOUR-SERVER.example.com/ingest/batch";
const INGEST_TOKEN = "PASTE-YOUR-FARM_TOKEN-HERE";
// ────────────────────────────────────────────────────────────────────────────

const BATCH = 50;      // ~8 KB per POST — cheap on a metered SIM
const LOCK_MS = 90000; // if a POST neither succeeds nor errors, unstick after this

const outbox = flow.get("outbox") || [];
if (outbox.length === 0) {
    node.status({ fill: "green", shape: "dot", text: "up to date" });
    return null;
}

// Don't stack POSTs on top of each other on slow 4G. The server dedupes anyway,
// but piling requests onto a marginal link only makes the link worse.
const lock = flow.get("pushLock") || 0;
if (Date.now() - lock < LOCK_MS) {
    node.status({ fill: "blue", shape: "ring", text: "sending… (" + outbox.length + " queued)" });
    return null;
}
flow.set("pushLock", Date.now());

const batch = outbox.slice(0, BATCH);

// NOTHING is removed from the outbox here. Items are only dropped once the server
// has confirmed 200. Delete-then-send loses data on every failed request.
msg.batchIds = batch.map(function (r) { return r.client_id; });
msg.url = INGEST_URL;
msg.headers = {
    "Content-Type": "application/json",
    "Authorization": "Bearer " + INGEST_TOKEN
};
msg.payload = { readings: batch };

node.status({ fill: "blue", shape: "dot", text: "sending " + batch.length + " of " + outbox.length });
return msg;

// Only a 200 that CAME FROM farm-ingest clears the buffer.
//
// Checking the status code alone is not enough: a misconfigured vhost, a captive
// portal, or a proxy error page all return 200 with a body that isn't ours. That
// would silently delete readings we never delivered — the worst possible failure
// for a store-and-forward queue. Demand the service's own {ok:true} envelope.
flow.set("pushLock", 0);

const body = msg.payload || {};
const delivered = msg.statusCode === 200 && body.ok === true && typeof body.accepted === "number";

if (!delivered) {
    // Surfaced on the local page too — a broken backhaul should be visible there,
    // not discovered by noticing the cloud dashboard stopped moving.
    flow.set("pushState", { ok: false, at: Date.now(), error: "HTTP " + msg.statusCode });
    node.status({ fill: "red", shape: "ring", text: "HTTP " + msg.statusCode + " — kept, will retry" });
    node.warn("farm-ingest did not confirm the batch (HTTP " + msg.statusCode + "): " +
              JSON.stringify(body).slice(0, 200));
    return null;
}
flow.set("pushState", { ok: true, at: Date.now(), error: null });

const sent = msg.batchIds || [];
const done = {};
sent.forEach(function (id) { done[id] = true; });

const outbox = (flow.get("outbox") || []).filter(function (r) { return !done[r.client_id]; });
flow.set("outbox", outbox);

// ── downlink: the valve command rides home on this response ─────────────────
//
// Applied on the EDGE of seq, never re-asserted. The local page's Open/Close
// buttons must keep working with no internet; if every push re-applied the cloud's
// state, a button pressed at the tank would be silently undone a minute later.
//
// On first contact we adopt the seq WITHOUT acting. Node-RED's context is in
// memory, so a restart forgets valveCmd and the valve falls shut — and it should
// STAY shut until a human asks again, rather than a stale cloud "open" re-opening
// it unattended. Fail closed is the only safe default for irrigation.
const v = body.valve;
if (v && typeof v.seq === "number") {
    const lastSeq = flow.get("valveSeq");
    if (lastSeq === undefined) {
        flow.set("valveSeq", v.seq);
    } else if (v.seq !== lastSeq) {
        flow.set("valveSeq", v.seq);
        flow.set("valveCmd", v.state ? 1 : 0);
        node.warn("valve " + (v.state ? "OPEN" : "SHUT") + " commanded from the cloud (seq " + v.seq + ")");
    }
}

node.status({
    fill: outbox.length ? "yellow" : "green",
    shape: "dot",
    text: "sent " + sent.length + " (" + (body.accepted || 0) + " new, " + (body.duplicates || 0) + " dup) · " + outbox.length + " queued"
});

// Anything still queued? Go straight round again instead of waiting to be poked.
//
// Without this, the tail of a burst sits undelivered until the NEXT reading happens
// to arrive — and on a dozing phone the 30 s inject that was supposed to cover that
// case never fires. Each pass strictly shrinks the outbox, so this terminates.
if (outbox.length > 0) return { payload: "continue" };
return null;

// Network-level failure: no signal, DNS down, TLS refused, timeout. The batch is
// still in the outbox untouched — clear the lock and let the next tick retry.
flow.set("pushLock", 0);
const queued = (flow.get("outbox") || []).length;
flow.set("pushState", { ok: false, at: Date.now(), error: "offline" });
node.status({ fill: "red", shape: "ring", text: "offline — " + queued + " queued" });
return null;
